// <auto-generated-by-handoff>
// Layer 1 — Uomd.Scenes: Master Unity 6 LTS Scene Router & Bootstrapper for all 28 UOMD screens.

using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;
using Uomd.Battle.Vfx;
using Uomd.Core;
using Uomd.Platform;
using Uomd.UI;

namespace Uomd.Scenes
{
    public interface IUomdScreenController
    {
        UomdScreenId ScreenId { get; }
        Awaitable OnEnterAsync(VisualElement screenRoot);
        void OnTick(float deltaTime);
        void OnExit();
    }

    [RequireComponent(typeof(UIDocument))]
    public sealed class UomdSceneRouter : MonoBehaviour
    {
        [SerializeField] private string apiBaseUrl = "https://uomd-game-staging.muratcaneksiii.workers.dev";
        [SerializeField] private Shader vfxBlendShader;

        private readonly Dictionary<UomdScreenId, IUomdScreenController> _controllers = new Dictionary<UomdScreenId, IUomdScreenController>();
        private UIDocument _uiDocument;
        private VisualElement _rootContainer;
        private VisualElement _headerBar;
        private VisualElement _screenHost;
        private VisualElement _overlayHost;
        private IUomdScreenController _activeController;

        public GameSessionState Session { get; private set; }
        public PatchManager Patch { get; private set; }
        public UomdApiClient Api { get; private set; }
        public IUomdPlatformBridge PlatformBridge { get; private set; }
        public AudioDirector Audio { get; private set; }
        public BattleVfxStage VfxStage { get; private set; }
        public UomdScreenId ActiveScreenId => _activeController?.ScreenId ?? UomdScreenId.Boot;

        private async void Awake()
        {
            Application.targetFrameRate = 60;
            Screen.sleepTimeout = SleepTimeout.NeverSleep;

            Session = new GameSessionState();
            Patch = new PatchManager();
            Api = new UomdApiClient(apiBaseUrl);
            PlatformBridge = UomdPlatformBridgeFactory.Create();
            Audio = gameObject.AddComponent<AudioDirector>();

            var vfxGo = new GameObject("UomdBattleVfxStage");
            vfxGo.transform.SetParent(transform, false);
            VfxStage = vfxGo.AddComponent<BattleVfxStage>();

            _uiDocument = GetComponent<UIDocument>();
            if (gameObject.GetComponent<SafeAreaBinder>() == null)
            {
                gameObject.AddComponent<SafeAreaBinder>();
            }

            BuildRootVisualTree();
            RegisterAll28Screens();

            await NavigateToAsync(UomdScreenId.Boot);
        }

        private void Update()
        {
            _activeController?.OnTick(Time.deltaTime);
        }

        public async Awaitable NavigateToAsync(UomdScreenId targetScreen)
        {
            if (!_controllers.TryGetValue(targetScreen, out var nextController))
            {
                Debug.LogWarning($"[UomdSceneRouter] Screen '{targetScreen}' is not registered.");
                return;
            }

            _activeController?.OnExit();
            _screenHost.Clear();

            _activeController = nextController;
            bool showHubHeader = targetScreen >= UomdScreenId.Home && targetScreen <= UomdScreenId.Operations;
            _headerBar.style.display = showHubHeader ? DisplayStyle.Flex : DisplayStyle.None;
            if (showHubHeader)
            {
                RefreshHeaderWallets(targetScreen.ToString().ToUpperInvariant());
            }

            await _activeController.OnEnterAsync(_screenHost);
        }

        public async Awaitable ToggleOverlayAsync(UomdScreenId overlayId)
        {
            _overlayHost.Clear();
            if (!_controllers.TryGetValue(overlayId, out var overlayController)) return;
            await overlayController.OnEnterAsync(_overlayHost);
        }

        public void ClearOverlays()
        {
            _overlayHost.Clear();
        }

        public void RefreshHeaderWallets(string screenTitle = null)
        {
            if (_headerBar == null || Session?.Account?.wallets == null) return;
            var titleLbl = _headerBar.Q<Label>("screen-title");
            if (titleLbl != null && !string.IsNullOrEmpty(screenTitle))
            {
                titleLbl.text = screenTitle;
            }

            var rationsLbl = _headerBar.Q<Label>("wallet-rations");
            if (rationsLbl != null) rationsLbl.text = $"Rations: {Session.Account.wallets.rations}";

            var goldLbl = _headerBar.Q<Label>("wallet-gold");
            if (goldLbl != null) goldLbl.text = $"Gold: {Session.Account.wallets.gold:N0}";

            var shardsLbl = _headerBar.Q<Label>("wallet-shards");
            if (shardsLbl != null) shardsLbl.text = $"Shards: {Session.Account.wallets.shards:N0}";

            var sealsLbl = _headerBar.Q<Label>("wallet-seals");
            if (sealsLbl != null) sealsLbl.text = $"Seals: {Session.Account.wallets.seals:N0}";
        }

        private void BuildRootVisualTree()
        {
            var root = _uiDocument.rootVisualElement;
            root.Clear();

            _rootContainer = new VisualElement { name = "safe-area-root" };
            _rootContainer.AddToClassList("uomd-root");
            _rootContainer.AddToClassList("uomd-safe-area");
            _rootContainer.style.flexGrow = 1f;

            // Shared Gothic Top Bar for Hub/Meta screens
            _headerBar = new VisualElement { name = "top-bar" };
            _headerBar.AddToClassList("uomd-header-bar");
            _headerBar.style.display = DisplayStyle.None;

            var backBtn = UomdUiKit.CreateButton("WORLD MAP", () => _ = NavigateToAsync(UomdScreenId.Home));
            var titleLbl = new Label("UNAWARE OF MY DEMISE") { name = "screen-title" };
            titleLbl.AddToClassList("uomd-title-md");

            var walletRow = new VisualElement();
            walletRow.style.flexDirection = FlexDirection.Row;

            walletRow.Add(CreatePill("wallet-rations", "Rations: 120"));
            walletRow.Add(CreatePill("wallet-gold", "Gold: 5,000"));
            walletRow.Add(CreatePill("wallet-shards", "Shards: 600"));
            walletRow.Add(CreatePill("wallet-seals", "Seals: 10"));

            _headerBar.Add(backBtn);
            _headerBar.Add(titleLbl);
            _headerBar.Add(walletRow);

            _screenHost = new VisualElement { name = "screen-host" };
            _screenHost.style.flexGrow = 1f;

            _overlayHost = new VisualElement { name = "overlay-host" };
            _overlayHost.pickingMode = PickingMode.Ignore;
            _overlayHost.style.position = Position.Absolute;
            _overlayHost.style.left = 0;
            _overlayHost.style.right = 0;
            _overlayHost.style.top = 0;
            _overlayHost.style.bottom = 0;

            _rootContainer.Add(_headerBar);
            _rootContainer.Add(_screenHost);
            _rootContainer.Add(_overlayHost);
            root.Add(_rootContainer);
        }

        private static Label CreatePill(string name, string text)
        {
            var pill = new Label(text) { name = name };
            pill.AddToClassList("uomd-wallet-pill");
            pill.AddToClassList("uomd-wallet-value");
            return pill;
        }

        private void RegisterAll28Screens()
        {
            // Group 1: Entry, Narrative & Tactical Combat (8 screens)
            Register(new BootScreenController(this));
            Register(new SplashScreenController(this));
            Register(new StudioScreenController(this));
            Register(new TitleScreenController(this));
            Register(new PrologueScreenController(this));
            Register(new StoryScreenController(this));
            Register(new BattleScreenController(this));
            Register(new FinishScreenController(this));

            // Group 2: World Map, Campaign, Roster, Summon & Trials (10 screens)
            Register(new HomeWorldMapScreenController(this));
            Register(new ChaptersScreenController(this));
            Register(new RosterScreenController(this));
            Register(new CharacterScreenController(this));
            Register(new GearScreenController(this));
            Register(new TeamScreenController(this));
            Register(new SummonScreenController(this));
            Register(new RecruitScreenController(this));
            Register(new ShopScreenController(this));
            Register(new TrialsScreenController(this));

            // Group 3: Tasks, Deeds, Social, Account, Monetization & Overlays (10 screens)
            Register(new TasksScreenController(this));
            Register(new DeedsScreenController(this));
            Register(new ProfileScreenController(this));
            Register(new MailScreenController(this));
            Register(new LibraryScreenController(this));
            Register(new AccountScreenController(this));
            Register(new PurchasesScreenController(this));
            Register(new OperationsScreenController(this));
            Register(new ContentPanelOverlayController(this));
            Register(new PatchBarOverlayController(this));
        }

        private void Register(IUomdScreenController controller)
        {
            _controllers[controller.ScreenId] = controller;
        }
    }
}
